 const base={stabbing:JSON.parse(fs.readFileSync(path.join(data,'stabbing.json'))),spec:JSON.parse(fs.readFileSync(path.join(data,'atlas.json'))),atlas:JSON.parse(fs.readFileSync(path.join(result,'atlas_cpp.json'))),witness:JSON.parse(fs.readFileSync(path.join(data,'frontier_witnesses.json'))),finite:JSON.parse(fs.readFileSync(path.join(root,'project/followup_c026/data/finite_comparison.json'))),pred:JSON.parse(fs.readFileSync(path.join(data,'predicates.json')))};
 const tree=fs.readFileSync(path.join(data,'atlas.tree'),'utf8'),cases=[];
 const neg=(id,kind,reason,fn)=>cases.push({id,kind,reason,positive:false,fn});const pos=(id,kind,fn)=>cases.push({id,kind,positive:true,fn});
