 neg('frontier_bad_bits','frontier','FRONTIER_PATH_BITS',x=>x.atlas.frontier_paths[0]='X'+x.atlas.frontier_paths[0].slice(1));
 neg('frontier_bad_witness','frontier','ILLEGAL_WITNESS',x=>x.witness.witnesses[0].pose.cx='100/1');
 neg('frontier_overlap','frontier','WITNESS_OVERLAP',x=>x.witness.witnesses[0].pose=clone(x.witness.anchor));
 neg('frontier_missing_path','frontier','WITNESS_NOT_IN_FRONTIER',x=>x.witness.witnesses[0].frontier_path='0'.repeat(18));
 neg('frontier_wide_box','frontier','BOX_WALL',x=>x.witness.witnesses[0].halfwidths=['1/1','1/1','1/1000']);
 neg('frontier_required_control','frontier','BOUNDARY_CONTROL_REQUIRED',x=>x.witness.open_boundary_control=false);
 neg('frontier_zero_scale','frontier','SCALE',x=>x.finite.scale='0');
 neg('frontier_dual_negative','frontier','DUAL_ENTRY',x=>x.finite.models.find(m=>m.id==='full_40_point_basis').dual[0].units='-1');
 neg('frontier_dual_sum','frontier','RETAINED_DUAL_SUM',x=>x.finite.models.find(m=>m.id==='full_40_point_basis').expected_dual_sum='1');
 neg('frontier_oversized_component','frontier','COMPONENT_NOT_CAPACITY_ONE',x=>{x.atlas.frontier_paths=[];for(let a=0;a<64;a++){const bits=a.toString(2).padStart(6,'0');x.atlas.frontier_paths.push([...bits].map(b=>b+'00').join(''));}x.atlas.counts.unresolved=64;});
 neg('quadratic_interior_false_positive','predicates','PREDICATE_EXPECTATION',x=>x.pred.cases[0].expected=true);
 neg('quadratic_strict_equality','predicates','PREDICATE_EXPECTATION',x=>x.pred.cases[2].expected=true);
 neg('quadratic_reversed_interval','predicates','PREDICATE_DOMAIN',x=>x.pred.cases[0].t=['1/1','0/1']);
 neg('quadratic_zero_bound','predicates','PREDICATE_DOMAIN',x=>x.pred.cases[0].bound='0/1');
 pos('smaller_near_angles','stabbing',x=>{for(const t of x.stabbing.targets){const[a,b]=t.near_t.split('/');t.near_t=a+'/'+(2n*BigInt(b));}});
 pos('narrower_seed_boxes','stabbing',x=>{for(const s of x.stabbing.seeds){s.ex='1/100';s.ey='1/100';s.et='1/200';}});
 pos('valid_coarse_outer_cover','atlas',x=>{x.spec.max_depth=0;x.tree='C028_ATLAS_V2\nU\n';});
 pos('equivalent_projection_scale','predicates',x=>{for(const c of x.pred.cases){for(const k of['dx','dy'])c[k]=c[k].map(s=>{const[a,b]=s.split('/');return(2n*BigInt(a))+'/'+b;});const[a,b]=c.bound.split('/');c.bound=(2n*BigInt(a))+'/'+b;}});
 pos('fewer_compatible_witnesses','frontier',x=>x.witness.witnesses=x.witness.witnesses.slice(0,3));
